import{_ as o,o as e,c as d,a2 as c}from"./chunks/framework.BUwdTBzS.js";const u=JSON.parse('{"title":"技术方案文档生成/更新","description":"","frontmatter":{"title":"技术方案文档生成/更新"},"headers":[],"relativePath":"dev-flow/references/tech-proposal-flow.md","filePath":"dev-flow/references/tech-proposal-flow.md","lastUpdated":null}'),a={name:"dev-flow/references/tech-proposal-flow.md"};function i(l,t,r,s,n,p){return e(),d("div",null,[...t[0]||(t[0]=[c('<blockquote><p>📄 本页由源文件 <code>skills/dev-flow/references/tech-proposal-flow.md</code> 自动投影生成（单一权威源）。请勿直接编辑本页。</p></blockquote><h1 id="技术方案文档生成-更新" tabindex="-1">技术方案文档生成/更新 <a class="header-anchor" href="#技术方案文档生成-更新" aria-label="Permalink to &quot;技术方案文档生成/更新&quot;">​</a></h1><blockquote><p>本文件由步骤 4 · 文档决策（环节 3/4） 的 文档平台 硬性决策环节按需加载。<strong>核心原则</strong>：decision 非 <code>skip</code> 时加载执行；<code>skip</code> 时不加载。</p></blockquote><h2 id="触发方式-硬性决策产物" tabindex="-1">触发方式（硬性决策产物） <a class="header-anchor" href="#触发方式-硬性决策产物" aria-label="Permalink to &quot;触发方式（硬性决策产物）&quot;">​</a></h2><p>步骤 4 · 文档决策（环节 3/4） 的 文档决策直接决定本文件是否加载和加载后的执行路径：</p><table tabindex="0"><thead><tr><th><code>doc_platform_tech_proposal.action</code></th><th>加载本文件？</th><th>执行路径</th></tr></thead><tbody><tr><td><code>create</code></td><td>✅ 加载</td><td>新建流程（doc-platform-doc 模式 A）</td></tr><tr><td><code>update</code></td><td>✅ 加载</td><td>更新流程（doc-platform-doc 模式 A 更新子流程 / 模式 C）</td></tr><tr><td><code>relink</code></td><td>❌ 不加载</td><td>仅读取文档获取 <code>locked_title</code> 后回写工作上下文（由 step-4-decision 内联处理）</td></tr><tr><td><code>skip</code></td><td>❌ 不加载</td><td>本轮完全跳过 文档平台</td></tr><tr><td><code>auto_inherited_skip</code></td><td>❌ 不加载</td><td>迭代修复继承首轮 skip，本轮跳过</td></tr></tbody></table><h2 id="前置检查-文档平台-空间探测结果" tabindex="-1">前置检查：文档平台 空间探测结果 <a class="header-anchor" href="#前置检查-文档平台-空间探测结果" aria-label="Permalink to &quot;前置检查：文档平台 空间探测结果&quot;">​</a></h2><p>步骤 4 · 文档决策（环节 3/4） 已完成探测并将结果写入工作上下文 YAML <code>doc_platform_space_probe</code>。本文件直接读取该字段，<strong>不重复探测</strong>。</p><p>探测协议详见 <code>steps/step-4-decision.md</code> §3.1「文档平台 空间探测协议」。</p><h3 id="决策与流程的映射" tabindex="-1">决策与流程的映射 <a class="header-anchor" href="#决策与流程的映射" aria-label="Permalink to &quot;决策与流程的映射&quot;">​</a></h3><table tabindex="0"><thead><tr><th>action</th><th>probe_layer</th><th>candidates</th><th>对应流程</th></tr></thead><tbody><tr><td><code>create</code></td><td>no_match / failed</td><td>空</td><td>新建流程：按模板生成并发布</td></tr><tr><td><code>create</code></td><td>matched</td><td>非空</td><td>新建流程（用户拒绝了已有文档，选择重新创建）</td></tr><tr><td><code>update</code></td><td>from_local</td><td>来自本地记录</td><td>更新流程：已有文档直接进入</td></tr><tr><td><code>update</code></td><td>matched</td><td>强/中匹配</td><td>更新流程：使用候选文档</td></tr><tr><td><code>relink</code></td><td>any</td><td>any</td><td>读取文档获取 locked_title → 写入工作上下文（本文件不执行）</td></tr></tbody></table><h2 id="新建流程-action-create" tabindex="-1">新建流程（action=create） <a class="header-anchor" href="#新建流程-action-create" aria-label="Permalink to &quot;新建流程（action=create）&quot;">​</a></h2><ol><li>调用 <code>use_skill(&#39;tech-doc&#39;)</code>（路由到 doc-platform-doc 模块，进入模式 A：从工作上下文提取信息）</li><li><strong>人员信息完整性校验</strong>：查询 任务平台 后，校验必填人员角色（产品、后台开发、PM、测试、前端开发）是否齐全。缺失时汇总报告给用户补充，<strong>补充完整后才继续生成文档</strong>。详见 doc-platform-doc 模块「关键人员信息校验规范」</li><li>按模板生成 Markdown 预览，<strong>必须使用 <code>ask_followup_question</code> 弹出交互式选项</strong>让用户确认：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>技术方案文档预览完毕，请选择：</span></span></code></pre></div><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>✅ 发布</td><td>确认内容无误，保存文档</td></tr><tr><td>✏️ 修改</td><td>告诉我需要调整的内容</td></tr><tr><td>⏭️ 跳过</td><td>本次不生成文档，直接进入步骤 4.5</td></tr></tbody></table><ol><li>用户选「发布」→ 保存文档到本地或平台</li><li><strong>回写工作上下文 YAML</strong>（关键，不可省略）：</li></ol><ul><li><code>doc_platform_tech_proposal.file_path</code> / <code>locked_title</code> 填充</li><li><code>status: synced</code>，<code>last_synced_at</code> 刷新</li><li><code>action_history</code> 追加 <code>action: created, user_choice: explicit_create, at: {now}, iteration: {current}</code> 条目</li></ul><ol><li>用户选「修改」→ 接收修改意见 → 更新文档 → 再次弹出选项</li><li>用户选「跳过」→ 更新 <code>doc_platform_tech_proposal.status = &quot;skipped&quot;</code>，<code>action_history</code> 追加 <code>action: skipped, user_choice: explicit_skip</code> 条目</li></ol><h2 id="更新流程-action-update" tabindex="-1">更新流程（action=update） <a class="header-anchor" href="#更新流程-action-update" aria-label="Permalink to &quot;更新流程（action=update）&quot;">​</a></h2><p>已有 技术方案文档时，<strong>不重新生成</strong>，而是基于本轮方案变更进行增量更新：</p><ol><li>通过工作上下文中的文档记录获取当前文档全文</li><li><strong>读取并校验 <code>locked_title</code></strong>：对比文档标题与 <code>locked_title</code>，不一致则告警（可能有人改过标题）</li><li><strong>人员信息完整性校验</strong>：检查已有文档中的必填人员角色是否齐全，如有缺失一并纳入变更清单</li><li>对比当前文档内容与本轮工作上下文中的方案/计划/范围变更，<strong>汇总整理出需要更新/调整/补充的内容</strong></li><li>按章节逐条列出变更清单，每条包含：</li></ol><ul><li>所在章节</li><li>当前内容（原文片段）</li><li>建议更新为（新内容片段）</li><li>变更原因</li></ul><ol><li><strong>必须使用 <code>ask_followup_question</code> 弹出交互式选项</strong>让用户决策更新方式：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已有 技术方案文档文档，以下是本轮需要更新的内容汇总。请选择更新方式：</span></span></code></pre></div><table tabindex="0"><thead><tr><th>选项</th><th>说明</th></tr></thead><tbody><tr><td>🤖 AI 直接更新</td><td>由我直接将变更内容更新到文档</td></tr><tr><td>📋 我自己更新</td><td>我参考以上汇总内容，自行更新</td></tr><tr><td>✏️ 调整变更内容</td><td>告诉我需要调整的变更项</td></tr><tr><td>⏭️ 跳过</td><td>本次不更新文档，直接进入步骤 4.5</td></tr></tbody></table><ol><li>用户选「AI 直接更新」→ 调用 <code>use_skill(&#39;tech-doc&#39;)</code>（路由到 doc-platform-doc 模块模式 C 方案 A），直接更新文档</li><li><strong>回写工作上下文 YAML</strong>（AI 直接更新成功时）：</li></ol><ul><li><code>last_synced_at</code> 刷新</li><li><code>action_history</code> 追加 <code>action: updated, user_choice: explicit_update, at: {now}, iteration: {current}, snapshot_sha: {sha256前6位}</code> 条目</li></ul><ol><li>用户选「我自己更新」→ 用户自行处理，直接进入步骤 4.5 / 步骤 5（<code>action_history</code> 不追加，因为本轮 AI 未执行更新）</li><li>用户选「调整变更内容」→ 接收修改意见 → 更新变更清单 → 再次弹出选项</li><li>用户选「跳过」→ 更新 <code>doc_platform_tech_proposal.status = &quot;outdated&quot;</code>（提醒后续步骤 7/10 兜底处理）</li></ol><blockquote><p>⚠️ <strong>注意</strong>：更新流程中，未涉及变更的章节必须保持原文不动，严禁全文重写。 ⚠️ <strong>标题保护</strong>：更新文档时 title 必须等于 <code>locked_title</code>，原样回传，禁止 AI 自行优化标题格式。</p></blockquote><h2 id="关联流程-action-relink-本文件不完整加载" tabindex="-1">关联流程（action=relink，本文件不完整加载） <a class="header-anchor" href="#关联流程-action-relink-本文件不完整加载" aria-label="Permalink to &quot;关联流程（action=relink，本文件不完整加载）&quot;">​</a></h2><p>当用户在阶段 3 选择&quot;🔗 关联该文档&quot;/&quot;🔗 关联已有文档&quot;/&quot;🔗 指定其他链接&quot;时：</p><ol><li><strong>不加载本文件</strong>，由 <code>step-4-decision.md</code> 内联处理</li><li>内联步骤：</li></ol><ul><li>读取文档获取当前 <code>title</code></li><li>写入工作上下文 YAML <code>doc_platform_tech_proposal</code>：</li><li><code>file_path</code> / <code>locked_title</code> 填充</li><li><code>status: synced</code>（视为已关联状态）</li><li><code>action_history</code> 追加 <code>action: relinked, user_choice: explicit_relink, at: {now}</code> 条目</li></ul><ol><li>本轮不执行任何 文档平台 写入操作，只建立关联</li></ol><h2 id="跳过流程-action-skip-auto-inherited-skip-本文件不加载" tabindex="-1">跳过流程（action=skip / auto_inherited_skip，本文件不加载） <a class="header-anchor" href="#跳过流程-action-skip-auto-inherited-skip-本文件不加载" aria-label="Permalink to &quot;跳过流程（action=skip / auto_inherited_skip，本文件不加载）&quot;">​</a></h2><ul><li><code>action=skip</code>：用户显式选择&quot;⏭️ 本次不处理&quot;</li><li><code>doc_platform_tech_proposal.status = &quot;skipped&quot;</code></li><li><code>action_history</code> 追加 <code>action: skipped, user_choice: explicit_skip</code> 条目</li><li><code>action=auto_inherited_skip</code>：迭代修复场景自动继承首轮 skip</li><li><code>action_history</code> 追加 <code>action: skipped, user_choice: auto_inherited</code> 条目</li></ul><p><strong>后续步骤 5/5.5/6 都不触发 文档平台 同步</strong>；步骤 7 / 步骤 10.3.5 由 closeout-flow §H.3+ / step-8-10-full §10.3.5 兜底对账子流程统一处理 （触发条件仅一条：<code>doc_platform_tech_proposal.file_path</code> 非空，与 <code>status == &quot;outdated&quot;</code> 解耦）。</p><h2 id="执行方式" tabindex="-1">执行方式 <a class="header-anchor" href="#执行方式" aria-label="Permalink to &quot;执行方式&quot;">​</a></h2><ul><li><strong>新建</strong>（<code>create</code>）：调用 <code>use_skill(&#39;tech-doc&#39;)</code>（路由到 doc-platform-doc 模块模式 A），在 dev-flow 上下文中自动填充生成</li><li><strong>更新</strong>（<code>update</code>）：调用 <code>use_skill(&#39;tech-doc&#39;)</code>（路由到 doc-platform-doc 模块模式 C），基于已有文档增量更新</li></ul><h2 id="排版要求" tabindex="-1">排版要求 <a class="header-anchor" href="#排版要求" aria-label="Permalink to &quot;排版要求&quot;">​</a></h2><p>tech-doc Skill 内置了完整的排版格式规范（空格规则、行内代码、标点符号、Mermaid 图表、专有名词大小写等），生成/更新文档时自动遵守，发布前执行自检清单。</p>',41)])])}const _=o(a,[["render",i]]);export{u as __pageData,_ as default};
